if [ -n "$CERT_FILE" ]; then
  if [ -f "$CERT_FILE"  ]; then
    /bin/busybox wget --tries=1 --spider --no-check-certificate -q https://localhost:3000/status || exit 1
    exit 0
  fi
fi

