	if len(cfg.Sms.BasicAuth) > 0 && strings.Contains(cfg.Sms.BasicAuth, ":") {
		s := strings.SplitN(cfg.Sms.BasicAuth, ":", 2)
		if len(s) == 2 {
			req.SetBasicAuth(strings.TrimSpace(s[0]), strings.TrimSpace(s[1]))
		}
	}
	if len(cfg.Sms.CustomHeader) > 0 && strings.Contains(cfg.Sms.CustomHeader, ":") {
		s := strings.SplitN(cfg.Sms.CustomHeader, ":", 2)
		if len(s) == 2 {
			req.Header.Add(strings.TrimSpace(s[0]), strings.TrimSpace(s[1]))
		}
	}
	req.Header.Add("Content-Type", cType)
	resp, _ := client.Do(req)
	log.Println(resp.Status)
}
=== userLogin (code -> session token) ===
	tmp := utils.Atoi(ps.ByName("tmp"))
	identity := ps.ByName("identity")
	mode := ps.ByName("mode")
	event := CreateAuditEvent("user login by "+mode, identity, mode, identity)
	defer func() { SaveAuditEvent(event, e.db, e.conf) }()

	if mode != "phone" && mode != "email" {
		ReturnError(w, r, "bad mode", 405, nil, event)
		return
	}

	userBson, err := e.db.lookupUserRecordByIndex(mode, identity, e.conf)
	if userBson == nil || err != nil {
		ReturnError(w, r, "internal error", 405, err, event)
		return
	}

	userTOKEN := utils.GetUuidString(userBson["token"])
	event.Record = userTOKEN
	// A login code must have been issued by prelogin first. If tempcode is
	// absent (user never called prelogin), reject: otherwise an unset code
	// would default to 0 and match a submitted "0", bypassing authentication.
	tempcodeRaw, ok := userBson["tempcode"]
	if !ok {
		ReturnError(w, r, "internal error", 405, nil, event)
		return
	}
	tmpCode := tempcodeRaw.(int32)
	// A real code is never 0 (RandNum(6) is 100000-999999); reject it outright.
	if tmp == 0 || tmp != tmpCode {
		ReturnError(w, r, "internal error", 405, nil, event)
		return
	}
	// Enforce the code expiration set by generateTempLoginCode (now + 60s).
	tempcodeexp := int32(0)
	if v, ok := userBson["tempcodeexp"]; ok {
		tempcodeexp = v.(int32)
	}
	if tempcodeexp == 0 || int32(time.Now().Unix()) > tempcodeexp {
		ReturnError(w, r, "internal error", 405, nil, event)
		return
	}
	// user entered correct key
	// generate temp user access code
	xtoken, hashedToken, err := e.db.genUserLoginXtoken(userTOKEN)
	//fmt.Printf("generate user access token: [REDACTED:value]\n", xtoken)
	if err != nil {
		ReturnError(w, r, "internal error", 405, err, event)
		return
	}
	event.Msg = "generated: " + hashedToken

